import {fields,certificateFields} from './importer.js';
import {certKinds} from './overview.js';
import {departmentsFor,unitType} from './structure.js';
export function templateSheets(schools,lookups=[]){
 const available=schools.filter(s=>s.is_active!==false),college=available.find(s=>unitType(s)==='college'),hq=available.find(s=>unitType(s)==='institute');
 const example=(code,s,position,department)=>({employee_code:code,full_name:'บุคลากร ตัวอย่าง',school_id:s?.name||'',position,department,work_unit:'',academic_rank:'ไม่มีวิทยฐานะ',birth_date:'1985-05-15',start_date:'2010-05-01',email:'example@example.org',phone:'0812345678',highest_education:'ปริญญาโท',education_majors:'การบริหารการศึกษา; เทคโนโลยีการศึกษา'});
 const examples=[...(college?[example('EXAMPLE001',college,'ครู',departmentsFor(college,lookups)[3])]:[]),...(hq?[example('EXAMPLE002',hq,'เจ้าหน้าที่',departmentsFor(hq,lookups)[0])]:[])];
 return [
 ['บุคลากร',[fields.map(f=>f[1])]],
 ['ใบรับรองวิชาชีพ',[certificateFields.map(f=>f[1])]],
 ['คำแนะนำ',[
 ['รายการ','คำชี้แจง'],
 ['รุ่นแม่แบบ','HRVec-Andaman2 รุ่น 1.9 ปรับตามข้อมูลล่าสุดวันที่ 22 ตุลาคม 2569'],
 ['บุคลากร','หนึ่งคนต่อหนึ่งแถว กรอกในชีต บุคลากร ตั้งแต่แถว 2'],
 ['ข้อมูลจำเป็น','บุคลากร: เลขที่ตำแหน่ง ชื่อ-นามสกุล หน่วยงาน/สถานศึกษา'],
 ['หน่วยงาน/สถานศึกษา','ส่วนกลางสถาบันและวิทยาลัย ใช้ชื่อเต็มจากชีต รายการอ้างอิง'],
 ['ฝ่าย','วิทยาลัยเลือกฝ่ายสถานศึกษา ส่วนกลางเลือกส่วนราชการสถาบัน ผู้อำนวยการเว้นว่างได้'],
 ['งาน/แผนก/กลุ่มงาน','กรอกงานที่ได้รับมอบหมายภายใต้ฝ่าย/ส่วนราชการ ช่องนี้เว้นว่างได้'],
 ['หลายสาขาวิชา','เฉพาะสาขาของวุฒิสูงสุด คั่นแต่ละสาขาด้วย ;'],
 ['หลายใบรับรอง','หนึ่งใบต่อหนึ่งแถวในชีต ใบรับรองวิชาชีพ ใช้เลขที่ตำแหน่งเดิมซ้ำ ไม่เพิ่มคอลัมน์'],
 ['ใบรับรองที่ต้องกรอก','เลขที่ตำแหน่ง ประเภทใบรับรอง ชื่อใบรับรองวิชาชีพ และหน่วยงานผู้ออก'],
 ['สมรรถนะทางวิชาชีพ','เลือก ใบรับรองสมรรถนะทางวิชาชีพ ระบุสาขาอาชีพ ระดับสมรรถนะ และมาตรฐานอ้างอิงตามหลักฐาน'],
 ['ช่องไม่ปรากฏในหลักฐาน','เว้นว่าง ไม่เดาวันหมดอายุหรือระดับสมรรถนะ'],
 ['วันที่','ใช้ YYYY-MM-DD ค.ศ. เช่น 2025-01-31 หรือวันที่ Excel ห้ามใช้ปี พ.ศ.'],
 ['เลขศูนย์นำหน้า','เลขที่ตำแหน่ง โทรศัพท์ และเลขที่ใบรับรอง ต้องเป็นข้อความ'],
 ['ไม่นำเข้า','ชีตตัวอย่างและรายการอ้างอิง ไม่ถูกนำเข้าอัตโนมัติ'],
 ['สถานะและที่อยู่','แม่แบบนี้ไม่มีช่องสถานะและที่อยู่ บุคลากรใหม่ใช้สถานะ ปฏิบัติงาน โดยอัตโนมัติ'],
 ['ข้อจำกัด','สูงสุด 500 คน / 5,000 ใบ / 100 ใบต่อคน / ไฟล์ไม่เกิน 5 MB'],
 ['การนำเข้า','ใช้เพิ่มบุคลากรใหม่ เลขที่ตำแหน่งต้องไม่ซ้ำกับข้อมูลเดิมในระบบ ใบรับรองต้องอ้างถึงคนในไฟล์เดียวกัน'],
 ['ก่อนส่ง','คงชื่อชีตและหัวคอลัมน์ ห้ามใส่สูตรหรือรหัสผ่าน เปิดหน้าตรวจสอบแล้วจึงยืนยันนำเข้า'],
 ['โครงสร้างสถานศึกษา','https://dles.vec.go.th/blog/47'],
 ['โครงสร้างสถาบัน','https://veis2.ac.th/government_structure/']]],
 ['รายการอ้างอิง',[
 ['รหัสหน่วยงาน','หน่วยงาน/สถานศึกษา','จังหวัด','ประเภทหน่วยงาน'],...available.map(s=>[s.id,s.name,s.province,unitType(s)==='institute'?'ส่วนกลางสถาบัน':'สถานศึกษา']),[],
 ['ประเภทหน่วยงาน','ฝ่าย/ส่วนราชการ'],...['college','institute'].flatMap(type=>departmentsFor({unit_type:type},lookups).map(d=>[type==='college'?'สถานศึกษา':'ส่วนกลางสถาบัน',d])),[],
 ['ประเภทใบรับรอง','ใช้สำหรับ'],...Object.entries(certKinds).map(([k,label])=>[label,{administrator:'ผู้บริหารสถานศึกษา',vocational:'ทักษะวิชาชีพเพิ่มเติม',competency:'สมรรถนะตามมาตรฐานอาชีพ',teacher_license:'ใบอนุญาตประกอบวิชาชีพครู'}[k]]),[],['หมวด','รายการ'],...lookups.filter(l=>['position','academic_rank'].includes(l.category)).map(l=>[l.category==='position'?'ตำแหน่ง':'วิทยฐานะ',l.name])]],
 ['ตัวอย่าง',[fields.map(f=>f[1]),...examples.map(p=>fields.map(([k])=>p[k]??''))]],
 ['ตัวอย่างใบรับรอง',[certificateFields.map(f=>f[1]),...['01','02'].map((suffix,i)=>[examples[0]?.employee_code||'EXAMPLE001',certKinds.competency,'คุณวุฒิวิชาชีพตัวอย่าง '+suffix,'หน่วยงานตัวอย่าง','CERT-'+suffix,'2025-01-01',i?'':'2028-01-01','เทคโนโลยีสารสนเทศ','ระดับ 4','มาตรฐานอาชีพตัวอย่าง'])]]
 ];
}
